	'messages:apihelp-query+random-param-maxsize' => 'lij:Lìmita a-e pàgine con a-o màscimo sto nùmero de byte chi.',
	'messages:apihelp-query+random-param-contentmodel' => 'lij:Fìltra e pàgine ch\'àn o modéllo de contegnûo specificòu.',
	'messages:apihelp-query+random-param-redirect' => 'lij:Dêuviâ pe cóntra <kbd>$1filterredir=redirects</kbd>.',
	'messages:apihelp-query+random-param-filterredir' => 'lij:Cómme filtrâ i rindirìssi.',
	'messages:apihelp-query+random-example-simple' => 'lij:O restitoìsce dôe pàgine abrétio da-o namespace prinçipâ.',
